def sum_list(nums):
    total = 0
    for n in nums:
        total += n
    return total

def max_in_list(nums):
    m = nums[0]
    for n in nums[1:]:
        if n > m:
            m = n
    return m

def is_palindrome(s):
    s = s.lower()
    return s == s[::-1]

def fizzbuzz(n):
    out = []
    for i in range(1, n+1):
        if i % 15 == 0:
            out.append('FizzBuzz')
        elif i % 3 == 0:
            out.append('Fizz')
        elif i % 5 == 0:
            out.append('Buzz')
        else:
            out.append(str(i))
    return out

def factorial(n):
    result = 1
    for i in range(2, n+1):
        result *= i
    return result

def two_sum(nums, target):
    seen = {}
    for i, v in enumerate(nums):
        if target - v in seen:
            return [seen[target - v], i]
        seen[v] = i

def flatten_once(lst):
