def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def word_freq(text):
    d = {}
    for w in re.findall(r"[A-Za-z']+", text.lower()):
        d[w] = d.get(w, 0) + 1
    return d

def read_nonempty_lines(path):
