def extract_emails(text):
    pat = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")
    return pat.findall(text)

import bisect

def running_median(nums):
    a = []
    out = []
    for n in nums:
        bisect.insort(a, n)
        m = len(a)
        if m % 2:
            out.append(float(a[m//2]))
        else:
            out.append((a[m//2-1] + a[m//2]) / 2)
    return out

