def window_sums(nums, k):
    if k <= 0 or k > len(nums):
        return []
    s = sum(nums[:k])
    out = [s]
    for i in range(k, len(nums)):
        s += nums[i] - nums[i-k]
        out.append(s)
    return out

def binary_search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def permutations(lst):
    if not lst:
        return [[]]
    out = []
    for i, x in enumerate(lst):
        rest = lst[:i] + lst[i+1:]
        for p in permutations(rest):
            out.append([x] + p)
    return out

import time

def timeit(func):
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        try:
            return func(*args, **kwargs)
        finally:
            end = time.perf_counter()
            wrapper.last_duration = end - start
    return wrapper

import os

class chdir:
    def __init__(self, path):
        self.path = path
        self.prev = None
    def __enter__(self):
        self.prev = os.getcwd()
        os.chdir(self.path)
        return self.path
    def __exit__(self, exc_type, exc, tb):
        os.chdir(self.prev)
        return False

from collections import OrderedDict

class LRU:
    def __init__(self, capacity):
        self.cap = capacity
        self.od = OrderedDict()
    def get(self, key):
        if key not in self.od:
            return None
        self.od.move_to_end(key)
        return self.od[key]
    def put(self, key, value):
        self.od[key] = value
        self.od.move_to_end(key)
        if len(self.od) > self.cap:
            self.od.popitem(last=False)

